import { test, expect } from '@playwright/test';

test('Test data TD-016: invalid', async ({ page }) => {
  console.log('[Timeline] Action: Navigate');
  await page.goto('https://www.saucedemo.com');

  const testData = {
    full_name: 'Alex Johnson',
    email: 'alex.johnson@demo.org',
    password: 'Secure#9',
    confirm_password: 'Secure#9',
    accept_terms: 'true',
  };

  console.log('[Timeline] Action: Fill Full Name');
  await page.getByLabel('Full Name').fill(testData.full_name);

  console.log('[Timeline] Action: Fill Email');
  await page.getByLabel('Email').fill(testData.email);

  console.log('[Timeline] Action: Fill Password');
  await page.getByLabel('Password').fill(testData.password);

  console.log('[Timeline] Action: Fill Confirm Password');
  await page.getByLabel('Confirm Password').fill(testData.confirm_password);

  console.log('[Timeline] Action: Check Accept Terms');
  await page.getByLabel('Accept Terms').check();

  console.log('[Timeline] Action: Submit Registration');
  // TODO: locator for submit button not specified in inputs — confirm against live DOM
  await page.locator('button').click();

  console.log('[Timeline] Assertion: Expect rejected_validation_error');
  await expect(page.getByText('rejected_validation_error')).toBeVisible({ timeout: 15000 });
});
